def supplemental_sources(name):
    links = ''.join(f'<li><a href="{url}" target="_blank" rel="noopener">{escape(label)}</a></li>' for label, url in SUPPLEMENTAL_SOURCES.get(name, []))
    return '<div class="supplemental-sources"><h3>منابع توضیح‌های تکمیلی</h3><p>ساختار درس‌ها بر پایهٔ جزوهٔ هر استاد است. برای روشن‌کردن بعضی تعریف‌ها و سازوکارها، از منابع زیر نیز استفاده شده است.</p><ul>'+links+'</ul></div>'

lessons = []
def en(t):
    if any('\u0600' <= c <= '\u06ff' for c in t): return t
    t=t.replace('←','→')
    return f'<bdi lang="en" dir="ltr">{t}</bdi>'
def ul(items): return '<ul>'+''.join(f'<li>{x}</li>' for x in items)+'</ul>'
def table(head, rows):
    return '<div class="table-wrap"><table><thead><tr>'+''.join(f'<th scope="col">{x}</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{x}</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def steps(items): return '<ol class="steps">'+''.join(f'<li>{x}</li>' for x in items)+'</ol>'
def refs(pages):
    return '<span class="refs">صفحه در جزوهٔ اصلی: '+ '، '.join(f'<a href="../%D8%A7%D8%B3%D8%AA%D8%A7%D8%AF%20%D8%AD%D8%A7%D8%AC%DB%8C%20%D8%AE%D8%A7%D9%86%DB%8C.pdf#page={p}" target="_blank" rel="noopener">{p}</a>' for p in pages)+'</span>'
def q(prompt, answer, points, pages, kind='تمرین درس'):
    return f'<div class="question"><span class="q-kind">{kind}</span><p class="q-prompt">{prompt}</p><details class="answer"><summary>نمایش پاسخ و نکات کلیدی</summary><div class="answer-body"><p>{answer}</p><strong>نکات کلیدی پاسخ:</strong>{ul(points)}{refs(pages)}</div></details></div>'
def lesson(part,title,pages,overview,goals,body,memory,questions,check):
    lessons.append(dict(part=part,title=title,pages=pages,overview=overview,goals=goals,body=body,memory=memory,questions=questions,check=check))

lesson(1,'از تاریخچه تا نام‌گذاری', [3,4],
 'برای شناخت یک باکتری، ابتدا باید جایگاه آن در طبقه‌بندی و شیوهٔ نام‌گذاری‌اش را بدانیم. این درس از کشف‌های مهم تاریخ میکروب‌شناسی شروع می‌کند و به تفاوت جنس، گونه و سویه می‌رسد.',
 ['برای هر دانشمند یک نقش کلیدی بگویم.','جنس، گونه و سویه را با مثال تفکیک کنم.','توضیح دهم چرا طبقه‌بندی به تشخیص کمک می‌کند.'],
 table(['نام','دستاورد اصلی'],[
 ['رابرت هوک','مشاهدهٔ سلول و به‌کاربردن نام سلول برای واحدهای مشاهده‌شده.'],
 ['لیوون‌هوک','مشاهدهٔ میکروارگانیسم‌ها با میکروسکوپ و توصیف آن‌ها با نام «جانورک‌ها».'],
 ['لویی پاستور','نقش میکروب‌ها در تخمیر و توسعهٔ پاستوریزاسیون؛ کاهش بار میکروبی با گرمای کنترل‌شده.'],
 ['جوزف لیستر','کاربرد فنل/اسید کربولیک برای کاهش عفونت پس از جراحی.'],
 ['رابرت کخ','شناسایی عامل سل؛ مایکوباکتریوم.'],
 ['ادوارد جنر','واکسن آبله.'],['الکساندر فلمینگ','مشاهدهٔ مهار رشد استاف اورئوس اطراف کپک پنی‌سیلیوم؛ کشف پنی‌سیلین.']])+ 
 '<p>در تاریخ میکروب‌شناسی، رد نظریهٔ پیدایش خودبه‌خودی و نشان‌دادن منشأ زیستی میکروب‌ها اهمیت داشت. برای مرور تاریخچه، «نام ← مشاهده یا اقدام ← نتیجه» را بنویس.</p>'+
 table(['اصطلاح','معنای ساده','مثال یا کاربرد'],[
 [en('طبقه‌بندی'),'قرار دادن جانداران در گروه‌های مشخص بر پایهٔ ویژگی‌های مشترک و روابط تکاملی.','گرم مثبت، گرم منفی، کوکسی، باسیل.'],
 [en('شناسایی'),'تعیین هویت نمونهٔ ناشناخته.','از رنگ گرم شروع می‌کنیم، سپس شکل، کشت و آزمایش‌ها را بررسی می‌کنیم.'],
 [en('رده‌بندی و نام‌گذاری'),'چارچوب رده‌بندی و نام‌گذاری موجودات.','حرکت از رده‌های کلی به جنس و گونه.'],
 ['جنس / گونه / سویه','جنس چند گونهٔ مرتبط را دربرمی‌گیرد. سویه، جمعیتی مشخص درون یک گونه است که از یک جدایه منشأ گرفته و می‌تواند ویژگی‌های متمایزی داشته باشد.',en('Escherichia coli')+'؛ در یک گونه، سویه‌ها می‌توانند ویژگی‌های متفاوت داشته باشند.']])+
 '<p>در نام علمی، نام جنس با حرف بزرگ و صفت گونه‌ای با حرف کوچک نوشته می‌شود: '+en('Staphylococcus epidermidis')+' و '+en('Mycobacterium leprae')+' (عامل جذام). ویژگی‌های ظاهری، ژنتیکی، بیوشیمیایی مثل مصرف لاکتوز و بیماری‌زایی همگی به طبقه‌بندی کمک می‌کنند.</p>'+
 '<p>منطق تشخیص: نمونهٔ ناشناخته ← رنگ گرم ← شکل و آرایش ← آزمایش‌های اختصاصی‌تر ← هویت احتمالی و انتخاب درمان هدفمند. همهٔ باکتری‌ها در رنگ گرم به‌خوبی بررسی نمی‌شوند؛ جزوه مایکوباکتریوم با دیوارهٔ متفاوت و مایکوپلاسما بدون دیواره را مثال می‌زند.</p>',
 'برای تاریخچه: «هوک = سلول؛ لیوون‌هوک = میکروب؛ پاستور = پاستوریزاسیون؛ لیستر = جراحی؛ کخ = سل؛ جنر = آبله؛ فلمینگ = پنی‌سیلین». این عبارت فقط برای به‌خاطر سپردن است.',
 [q('فرق طبقه‌بندی و شناسایی چیست؟','اولی یک موجود را در گروهی با ویژگی‌های مشترک قرار می‌دهد؛ دومی هویت نمونهٔ مشخص و ناشناخته را تعیین می‌کند. طبقه‌بندی دامنهٔ جست‌وجوی شناسایی را کوچک می‌کند.',['گروه‌بندی در برابر تعیین هویت','مثال رنگ گرم و ادامهٔ آزمایش‌ها'],[3,4]),
 q('در Escherichia coli، جنس و گونه را مشخص کنید و سویه را توضیح دهید.','Escherichia نام جنس و coli صفت گونه‌ای است؛ نام کامل گونه Escherichia coli است. سویه جمعیتی مشخص درون یک گونه است که ممکن است ویژگی متمایزی، مانند الگوی مقاومت، داشته باشد.',['جنس و صفت گونه‌ای','حرف بزرگ جنس و کوچک گونه','سویه با ویژگی متمایز'],[4])],
 ['می‌توانم نام‌ها و نقش‌ها را بدون نگاه کردن مرتبط کنم.','می‌توانم جنس، گونه و سویه را با یک مثال توضیح دهم.'])

lesson(1,'چند راه برای دسته‌بندی یک باکتری',[4,5,6,7],
 'شکل، آرایش سلول‌ها، نیاز به اکسیژن، دما و pH، هر کدام بخشی از ویژگی‌های باکتری را توصیف می‌کنند. کنار هم گذاشتن این ویژگی‌ها به شناخت و شناسایی آن کمک می‌کند.',
 ['همسفره و فرصت‌طلب را با مثال توضیح دهم.','چهار الگوی اکسیژنی و کاپنوفیل را تفکیک کنم.','حداقل، حداکثر و دمای بهینه را اشتباه نگیرم.'],
 '<p><strong>بیماری‌زایی:</strong> پاتوژن یعنی عامل بیماری‌زا. باکتری فرصت‌طلب معمولاً وقتی بیماری ایجاد می‌کند که دفاع میزبان تضعیف شود یا به محل نامعمولی راه یابد. '+en('E. coli')+' در روده بخشی از میکروبیوتای طبیعی است، ولی ورود آن به مجاری ادراری با عفونت ارتباط دارد. همسفرگی '+' رابطه‌ای است که در آن یک طرف سود می‌برد و سود یا زیان آشکاری به طرف دیگر نمی‌رسد؛ تغییر شرایط می‌تواند این رابطه را عوض کند.</p>'+
 table(['شکل یا آرایش','تصویر ذهنی'],[['کوکسی / باسیل','کروی / میله‌ای'],['اسپیریل / اسپیروکت','مارپیچی / پیچی'],['ویبریو / رشته‌ای','خمیده یا هلالی / رشته‌ای یا منشعب'],['دیپلوکوک / زنجیره / خوشه','جفت کوکسی / الگوی استرپ / الگوی استاف']])+
 '<p>شکل و آرایش سرنخ‌اند، نه شناسایی نهایی. در جزوه، دیپلوکوک ممکن است به پنوموکوک و آرایش زنجیره یا خوشه به استرپ یا استاف راهنمایی کند.</p>'+
 table(['نیاز گازی','شرح جزوه','خواندن شکل صفحهٔ ۶'],[
 [en('هوازی اجباری'),'برای رشد به اکسیژن وابسته است.','تراکم رشد در بالای لوله، نزدیک اکسیژن.'],
 [en('بی‌هوازی اجباری'),'اکسیژن و ترکیبات واکنش‌پذیر آن برایش زیان‌آورند.','رشد در پایین لوله، دور از اکسیژن.'],
 [en('بی‌هوازی اختیاری'),'در حضور و نبود اکسیژن امکان رشد دارد.','در سراسر لوله؛ تراکم بالاتر در بالا.'],
 [en('کم‌اکسیژن‌دوست'),'اکسیژن می‌خواهد ولی با غلظت کمتر از هوای معمول؛ حدود ۵٪ در جزوه.','نواری کمی پایین‌تر از سطح.'],
 [en('دی‌اکسیدکربن‌دوست'),'برای رشد بهتر به CO₂ بیشتر نیاز دارد.','این برچسب نیاز به CO₂ را بیان می‌کند؛ با چهار الگوی قبلی یکی نیست.']])+
 table(['دستهٔ دمایی','اعداد و توصیف در جزوه'],[
 ['سرمادوست / سرماتحمل','سرمادوست در دمای پایین بهترین رشد را دارد؛ سرماتحمل می‌تواند در سرما رشد کند، اما دمای بهینه‌اش بالاتر است.'],
 ['مزوفیل','دمای بهینه در محدودهٔ میانه قرار دارد؛ بسیاری از عوامل انسانی در دمای نزدیک بدن خوب رشد می‌کنند. حدود دقیق به گونه وابسته است.'],
 ['ترموفیل','حدود ۵۰ تا ۸۰ درجه.'],['هایپرترموفیل','بالاتر از ۸۰ درجه؛ مثال زیستگاه: چشمهٔ آب گرم و محیط‌های بسیار داغ.']])+
 '<p><strong>حداقل</strong> یعنی پایین‌ترین حد تحمل/رشد مطرح‌شده، <strong>حداکثر</strong> بالاترین حد و <strong>بهینه</strong> بهترین مقدار برای رشد. شکل‌های دما و pH نشان می‌دهند «امکان تحمل» با «بیشترین رشد» یکسان نیست.</p>'+
 '<p>بر پایهٔ pH: <strong>اسیدوفیل</strong> محیط اسیدی، <strong>نوتروفیل</strong> محیط نزدیک خنثی و <strong>آلکالوفیل/بازوفیل</strong> محیط قلیایی را ترجیح می‌دهد. جمع‌بندی جزوه دربارهٔ بسیاری از پاتوژن‌های انسانی: بی‌هوازی اختیاری + مزوفیل + نوتروفیل؛ این جمع‌بندی به معنی نبود پاتوژن در دسته‌های دیگر نیست.</p>',
 'شش سؤال برای توصیف باکتری: «چه شکلی؟ چه آرایشی؟ در چه شرایطی بیماری‌زا؟ چه اکسیژنی؟ چه دمایی؟ چه pH؟»',
 [q('چرا E. coli می‌تواند هم میکروبیوتای طبیعی و هم عامل عفونت باشد؟','محل و شرایط اهمیت دارند. جزوه حضور در روده را طبیعی و انتقال به مجاری ادراری را نمونهٔ بیماری‌زایی فرصت‌طلب معرفی می‌کند.',['محل طبیعی','جابه‌جایی','شرایط میزبان'],[5]),
 q('بی‌هوازی اختیاری، میکروآئروفیل و کاپنوفیل را مقایسه کنید.','اختیاری با و بدون اکسیژن رشد می‌کند؛ میکروآئروفیل به اکسیژن کمتر از هوای معمول نیاز دارد؛ کاپنوفیل رشد بهتر با CO₂ بیشتر دارد.',['سه نیاز متفاوت','کاپنوفیل را با بی‌هوازی یکی نکن'],[6]),
 q('طبق جزوه بیشتر پاتوژن‌های انسانی از نظر اکسیژن، دما و pH در چه دسته‌هایی‌اند؟','بیشتر در دسته‌های بی‌هوازی اختیاری، مزوفیل و نوتروفیل قرار می‌گیرند، ولی جزوه وجود آن‌ها در دسته‌های دیگر را هم می‌پذیرد.',['هر سه معیار','قید «بیشتر»، نه «همه»'],[6,7])],
 ['چهار الگوی اکسیژنی را از حفظ می‌نویسم.','می‌توانم فرق تحمل و رشد بهینه را توضیح دهم.'])

lesson(1,'داخل سلول: دی‌ان‌ای، ریبوزوم و غشا',[7,8,10,11],
 'باکتری هستهٔ غشادار و میتوکندری ندارد. دی‌ان‌ای در نوکلئوئید قرار می‌گیرد، ریبوزوم پروتئین می‌سازد و غشای سیتوپلاسمی در انتقال مواد و تولید انرژی نقش دارد.',
 ['کروموزوم، پلاسمید و نوکلئوئید را جدا کنم.','علت جمع‌نشدن عددهای S را توضیح دهم.','محل سنتز پروتئین و زنجیرهٔ انتقال الکترون را بگویم.'],
 table(['جزء','کار و نکته'],[
 ['سیتوپلاسم','فضای ژله‌مانند درون غشا؛ محل بسیاری از واکنش‌های متابولیک. میتوکندری و شبکهٔ آندوپلاسمی ندارد.'],
 ['نوکلئوئید','ناحیهٔ تجمع مادهٔ ژنتیکی بدون هستهٔ واقعی/غشادار.'],
 ['کروموزوم','معمولاً دی‌ان‌ای بزرگ حلقوی و دورشته‌ای، حامل ژن‌های ضروری.'],
 ['پلاسمید','دی‌ان‌ای کوچک‌تر خارج‌کروموزومی با همانندسازی مستقل؛ ممکن است ژن مقاومت یا بیماری‌زایی داشته باشد و الزامی نیست.'],
 ['ریبوزوم','سنتز پروتئین بر اساس آر‌ان‌ای پیام‌رسان؛ در باکتری 70S از زیرواحدهای 30S و 50S.'],
 ['غشای سیتوپلاسمی','دولایهٔ لیپیدی با پروتئین‌ها؛ فسفولیپیدها سر قطبی و زنجیره‌های چربی دارند. زنجیرهٔ انتقال الکترون در غشای داخلی انجام می‌شود.']])+
 '<h4>چرا ۳۰ + ۵۰ در اینجا ۷۰ می‌شود؟</h4><p>'+en('واحد سوِدبرگ (S)')+' ضریب مرتبط با رسوب ذره در سانتریفیوژ است، نه یک واحد جمع‌پذیر مانند جرم. شکل و رفتار مجموعهٔ متصل با دو جزء جدا فرق دارد. بنابراین ریبوزوم باکتری '+en('30S + 50S ← 70S')+' است؛ در یوکاریوت '+en('40S + 60S ← 80S')+'. این نمایش به معنی جمع حسابی اعداد نیست.</p>'+
 '<p>برای توصیف هر جزء سلول، نام، محل قرارگیری و کارکرد آن را کنار هم بنویس. در گرم منفی، غشای خارجی را با غشای سیتوپلاسمی که محل انتقال الکترون است اشتباه نگیر.</p>',
 'نوکلئوئید = محل دی‌ان‌ای؛ ریبوزوم = ساخت پروتئین؛ غشای داخلی = انتقال الکترون. این سه مکان را روی یک سلول فرضی نام‌گذاری کن.',
 [q('ریبوزوم باکتری از چه زیرواحدهایی تشکیل می‌شود و چرا جمع عددها با عدد نهایی برابر نیست؟','ریبوزوم 70S از 30S و 50S ساخته می‌شود. S رفتار رسوبی را بیان می‌کند و با اتصال زیرواحدها شکل و رفتار مجموعه تغییر می‌کند؛ پس جمع حسابی معتبر نیست.',['70S، 30S، 50S','Svedberg','تغییر شکل و رفتار رسوبی'],[8]),
 q('کروموزوم، پلاسمید و نوکلئوئید را مقایسه کنید.','کروموزوم مادهٔ ژنتیکی اصلی است؛ پلاسمید دی‌ان‌ای کوچک‌تر با همانندسازی مستقل است؛ نوکلئوئید ناحیه‌ای است که دی‌ان‌ای در آن متمرکز می‌شود و خودش یک مولکول جداگانه نیست.',['مادهٔ اصلی','عنصر خارج‌کروموزومی','ناحیه در برابر مولکول'],[7,10]),
 q('با نبود میتوکندری، زنجیرهٔ انتقال الکترون باکتری کجا انجام می‌شود؟','طبق جزوه در غشای سیتوپلاسمی/داخلی؛ بسیاری از واکنش‌های دیگر در سیتوپلاسم‌اند.',['غشای داخلی','تفاوت با میتوکندری یوکاریوت'],[11])],
 ['از حفظ یک سلول ساده رسم و اجزای اصلی را نام‌گذاری می‌کنم.','توضیح 70S را بدون گفتن «خطای ریاضی» می‌نویسم.'])

lesson(1,'دیواره و ابزارهای بیرونی',[8,9,10,11,12],
 'دیواره به سلول شکل و استحکام می‌دهد. کپسول به حفاظت، پیلی به اتصال یا انتقال ژن و تاژک به حرکت کمک می‌کند؛ هر ساختار را با کارکردش بشناس.',
 ['گرم مثبت و منفی را از نظر لایه‌ها مقایسه کنم.','سه بخش LPS را نام ببرم.','کپسول، اسلایم، پیلی و تاژک را با هم اشتباه نگیرم.'],
 '<p>پپتیدوگلیکان با شبکهٔ قندها و اتصالات پپتیدی به حفظ شکل و جلوگیری از ترکیدن سلول بر اثر فشار اسمزی کمک می‌کند. دیواره در حفاظت محیطی و تعامل با میزبان نیز نقش دارد.</p>'+
 table(['ویژگی','گرم مثبت','گرم منفی'],[
 ['پپتیدوگلیکان','ضخیم؛ جزوه حدود ۵۰ تا ۹۰٪ وزن خشک دیواره را ذکر می‌کند.','نازک‌تر، در فضای بین غشای داخلی و خارجی.'],
 ['غشای خارجی','ندارد.','دارد؛ LPS و لیپوپروتئین در این ساختار مطرح‌اند.'],
 ['تیکوئیک / لیپوتیکوئیک اسید','حضور دارند؛ نقش آنتیژنی.','تیکوئیک اسید ندارد.'],
 ['رنگ نهایی گرم','بنفش','صورتی/قرمز']])+
 '<p><strong>لیپوپلی‌ساکارید (LPS)</strong> در لایهٔ بیرونی غشای خارجی باکتری‌های گرم منفی قرار دارد و در التهاب، تب‌زایی و ویژگی‌های آنتی‌ژنی نقش دارد. سه جزء: '+en('لیپید A')+' بخش سمی، '+en('بخش مرکزی')+' بخش قندیِ مرکزی و '+en('آنتی‌ژن O')+' بخش پلی‌ساکاریدی بیرونی است. لیپید A در غشا جای می‌گیرد و زنجیرهٔ O به سمت بیرون امتداد دارد.</p>'+
 table(['جزء بیرونی','نقش و تمایز'],[
 ['کپسول','لایهٔ منظم‌تر و محکم‌تر؛ حفاظت در برابر خشکی، عوامل محیطی و فاگوسیتوز؛ کمک به اتصال و بیوفیلم. در رنگ‌آمیزی معمول ممکن است هاله دیده شود.'],
 ['اسلایم','شل‌تر، کمتر متصل و آسان‌تر قابل شست‌وشو از کپسول.'],
 ['پیلی ','بعضی برای چسبندگی، بعضی پیلی جنسی برای انتقال دی‌ان‌ای در انتقال تماسی (هم‌یوغی).'],
 ['تاژک ','حرکت؛ ممکن است در یک قطب، دو قطب یا پیرامون سلول باشد. همهٔ باکتری‌ها تاژک ندارند.']])+
 '<p><strong>Virulence</strong> درجهٔ توان یک عامل برای ایجاد بیماری یا آسیب در میزبان است. در جزوه، کپسول با فرار از ایمنی، پیلی با اتصال و تاژک با حرکت به این توان کمک می‌کنند؛ وجود یک ساختار به‌تنهایی مساوی بیماری نیست.</p>',
 'کپسول = حفاظت؛ پیلی = اتصال/انتقال؛ تاژک = حرکت. برای LPS از بیرون به داخل: آنتی‌ژن O، بخش مرکزی، لیپید A.',
 [q('دیوارهٔ گرم مثبت و گرم منفی را در چهار محور مقایسه کنید.','گرم مثبت پپتیدوگلیکان ضخیم، بدون غشای خارجی و دارای تیکوئیک/لیپوتیکوئیک اسید است؛ گرم منفی پپتیدوگلیکان نازک‌تر بین دو غشا و LPS در غشای خارجی دارد. رنگ نهایی به ترتیب بنفش و صورتی است.',['ضخامت','غشای خارجی','ترکیبات شاخص','رنگ'],[9,11,12]),
 q('LPS از چه بخش‌هایی ساخته شده و بخش سمی آن چیست؟','لیپید A، بخش قندیِ مرکزی و آنتی‌ژن O؛ بخش سمی لیپید A است.',['سه نام','نقش لیپید A','محل: غشای خارجی گرم منفی'],[11,12]),
 q('دو نقش پیلی و یک نقش تاژک را بنویسید.','پیلی در اتصال و در نوع جنسی در انتقال مادهٔ ژنتیکی نقش دارد. تاژک ابزار حرکت است.',['اتصال','انتقال دی‌ان‌ای','حرکت'],[10])],
 ['جدول گرم مثبت/منفی را از حفظ بازسازی می‌کنم.','برای هر ساختار بیرونی یک کار مشخص می‌نویسم.'])

lesson(1,'رنگ گرم و شکل مقاوم اندوسپور',[10,11,12],
 'رنگ‌آمیزی گرم، تفاوت ساختمان پوشش سلولی را به تفاوت رنگ تبدیل می‌کند. اندوسپور هم شکل مقاومی برای بقای بعضی باکتری‌ها در شرایط نامساعد است.',
 ['ترتیب مراحل گرم را همراه با نتیجهٔ رنگ بنویسم.','مرحلهٔ حساس رنگ‌زدایی را مشخص کنم.','چرخهٔ حالت فعال و اندوسپور را توضیح دهم.'],
 steps(['تهیهٔ اسمیر از کشت و تثبیت با گرما: اتصال نمونه به لام و کاهش جداشدن هنگام شست‌وشو.','کریستال بنفش، حدود یک دقیقه در جزوه: هر دو گروه بنفش.','لوگول: همراهی با رنگ اولیه؛ هر دو گروه هنوز بنفش.','رنگ‌زدایی با الکل، استون یا مخلوط: گرم مثبت بنفش باقی می‌ماند؛ گرم منفی رنگ اولیه را از دست می‌دهد.','سافرانین یا فوشین: گرم منفی صورتی/قرمز دیده می‌شود؛ گرم مثبت بنفش باقی می‌ماند.'])+
 '<p><strong>نقطهٔ حساس:</strong> رنگ‌زدایی بیش‌ازحد یا طولانی می‌تواند نتیجه را اشتباه کند. نتیجهٔ گرم علاوه بر رنگ، شکل و آرایش را هم نشان می‌دهد و دامنهٔ بررسی را کوچک می‌کند.</p>'+
 '<h4>اندوسپور: چرخهٔ بقا</h4>'+steps(['شرایط محیطی نامساعد می‌شود.','در برخی باکتری‌ها دی‌ان‌ای در ناحیه‌ای با چند لایهٔ محافظ قرار می‌گیرد و شکل مقاوم ایجاد می‌شود.','شکل مقاوم در محیط باقی می‌ماند.','با مساعد شدن شرایط، به باکتری فعال برمی‌گردد.'])+
 '<p>مثال جزوه عامل کزاز است: اندوسپور در خاک می‌ماند، از زخم وارد بدن می‌شود و در شرایط مناسب شکل فعال و تولید سم با بیماری ارتباط پیدا می‌کنند. همهٔ باکتری‌ها اندوسپور ندارند. نقش مطرح‌شده در این بخش <strong>بقا در شرایط نامساعد</strong> است.</p>',
 '«تثبیت ← بنفش ← لوگول ← رنگ‌زدایی ← رنگ مقابل». هنگام مرور، بعد از هر مرحله رنگ هر دو گروه را بنویس؛ فقط نام مواد کافی نیست.',
 [q('مراحل رنگ‌آمیزی گرم و رنگ دو گروه را توضیح دهید.','اسمیر و تثبیت، کریستال بنفش، لوگول، رنگ‌زدایی و رنگ مقابل. تا پیش از رنگ‌زدایی هر دو بنفش‌اند؛ در رنگ‌زدایی گرم منفی بی‌رنگ می‌شود؛ پس از رنگ مقابل گرم مثبت بنفش و گرم منفی صورتی/قرمز است.',['ترتیب پنج مرحله','تغییر رنگ هر گروه','اهمیت رنگ‌زدایی'],[10,11]),
 q('اندوسپور چگونه به بقای عامل کزاز کمک می‌کند؟','اندوسپور شکل مقاومی است که در شرایط نامساعد در خاک می‌ماند. پس از ورود از زخم و مساعد شدن شرایط، باکتری فعال می‌شود و می‌تواند سم تولید کند.',['شکل مقاوم','خاک و زخم','بازگشت به حالت فعال','تولید سم'],[12])],
 ['مراحل گرم را همراه با رنگ‌ها از حفظ می‌نویسم.','کپسول و اندوسپور را به‌عنوان دو ساختار متفاوت توضیح می‌دهم.'])

lesson(2,'تقسیم دوتایی و منحنی رشد',[14,15],
 'رشد جمعیت باکتری یعنی افزایش تعداد سلول‌ها. تقسیم دوتایی این افزایش را ممکن می‌کند و منحنی رشد نشان می‌دهد سرعت افزایش جمعیت در طول زمان چگونه تغییر می‌کند.',
 ['مراحل تقسیم دوتایی را مرتب کنم.','زمان دوبرابرشدن را تعریف کنم.','چهار فاز رشد را با تغییر جمعیت و علت آن توضیح دهم.'],
 steps(['سلول بزرگ‌تر می‌شود و دی‌ان‌ای همانندسازی می‌شود.','ژنوم‌های حاصل از هم جدا می‌شوند و سلول طویل می‌شود.','غشا و دیواره رشد می‌کنند و سپتوم/دیوارهٔ جداکننده شکل می‌گیرد.','دو سلول دختر از هم جدا می‌شوند.'])+
 '<p><strong>زمان نسل / زمان دوبرابرشدن:</strong> میانگین زمان لازم برای دوبرابرشدن جمعیت. زمان طولانی‌تر یعنی رشد کندتر. اعداد مثال جزوه: E. coli حدود ۲۰ تا ۳۰ دقیقه؛ M. tuberculosis حدود ۲۰ ساعت؛ برای بعضی گونه‌ها ۴۸ ساعت یا حتی یک هفته ذکر شده است. این‌ها مثال‌های جزوه‌اند و شرایط رشد در این اعداد مهم است.</p>'+
 '<p>نشانهٔ رشد در محیط <strong>جامد</strong> تشکیل کلنی و در محیط <strong>مایع</strong> کدورت است.</p>'+
 table(['فاز','چه رخ می‌دهد؟','علت یا نکتهٔ مهم'],[
 [en('تأخیری'),'افزایش محسوس تعداد دیده نمی‌شود.','سازگاری با محیط جدید؛ «عدم افزایش تعداد» را با بی‌فعالیتی کامل یکی نکن.'],
 [en('نمایی'),'افزایش نمایی جمعیت.','جزوه بیشترین حساسیت به آنتی‌بیوتیک‌ها را در این فاز مطرح می‌کند.'],
 [en('سکون'),'تعداد کل تقریباً ثابت؛ تکثیر و مرگ در تعادل.','کاهش غذا و تجمع مواد زائد؛ ثابت بودن جمعیت یعنی تعادل، نه توقف همهٔ سلول‌ها.'],
 [en('مرگ'),'کاهش جمعیت زنده.','مرگ از ایجاد سلول جدید بیشتر می‌شود.']])+
 '<div class="curve" role="img" aria-label="نمای شماتیک چهار فاز رشد: سازگاری، افزایش، تعادل و کاهش؛ محور افقی زمان و محور عمودی لگاریتم تعداد سلول زنده است."><svg viewBox="0 0 640 210" xmlns="http://www.w3.org/2000/svg"><title>منحنی شماتیک رشد جمعیت باکتری</title><path d="M45 20V172H615" fill="none" stroke="currentColor" stroke-width="2"/><path d="M55 151H145C185 151 207 48 285 48H410C445 48 469 142 585 160" fill="none" stroke="#20766c" stroke-width="5"/><g fill="currentColor" font-size="16" font-family="Tahoma" text-anchor="middle"><text x="100" y="195">تأخیری</text><text x="220" y="195">نمایی</text><text x="345" y="195">سکون</text><text x="520" y="195">مرگ</text></g></svg><p class="caption">زمان از چپ به راست؛ ارتفاع مسیر نمایندهٔ لگاریتم تعداد سلول زنده است. شکل آموزشی، بازترسیم شماتیک مفهوم صفحهٔ ۱۴ است و دادهٔ اندازه‌گیری‌شده ندارد.</p></div>',
 'چهار فعل: «سازگار می‌شود ← زیاد می‌شود ← تعداد متعادل می‌شود ← کم می‌شود». منحنی را بکش و علت هر قسمت را کنار آن بنویس.',
 [q('سکون با توقف کامل تقسیم چه فرقی دارد؟','در فاز سکون، کاهش غذا و تجمع مواد زائد باعث تعادل تقریبی تولید و مرگ می‌شود؛ تعداد ثابت الزاماً به معنی تقسیم‌نکردن تک‌تک سلول‌ها نیست.',['تعادل تکثیر و مرگ','کاهش غذا و مواد زائد','جمعیت در برابر تک‌سلول'],[15]),
 q('چهار فاز رشد را به ترتیب با یک ویژگی بنویسید.','تأخیری: سازگاری؛ نمایی: افزایش نمایی؛ سکون: تعادل تکثیر و مرگ؛ مرگ: کاهش تعداد زنده.',['ترتیب','ویژگی هر فاز'],[14,15]),
 q('زمان دوبرابرشدن چیست و رشد در کشت جامد و مایع چگونه دیده می‌شود؟','زمان لازم برای دوبرابرشدن جمعیت است. در جامد کلنی و در مایع کدورت نشانهٔ رشدند.',['تعریف جمعیتی','کلنی','کدورت'],[14])],
 ['منحنی را با چهار برچسب از حفظ رسم می‌کنم.','تقسیم دوتایی را در چهار مرحله توضیح می‌دهم.'])

lesson(2,'غذا، انرژی و سه مسیر متابولیک',[15,16],
 'منبع کربن، مادهٔ لازم برای ساخت اجزای سلول را فراهم می‌کند؛ منبع انرژی، توان انجام واکنش‌ها را. پس از شناخت این تفاوت، تنفس هوازی، تنفس بی‌هوازی و تخمیر را مقایسه می‌کنیم.',
 ['منبع کربن و انرژی را تفکیک کنم.','نقش عناصر و سیدروفور را بگویم.','تخمیر را با تنفس بی‌هوازی یکسان ندانم.'],
 table(['نیاز','نکتهٔ جزوه'],[
 ['کربن','اتوتروف: CO₂ را به‌عنوان منبع کربن برای ساخت ترکیبات آلی به کار می‌برد؛ هتروتروف: کربن را از ترکیبات آلی می‌گیرد. پاتوژن‌ها در جزوه هتروتروف معرفی شده‌اند.'],
 ['نیتروژن','جزء سازندهٔ پروتئین، آر‌ان‌ای، دی‌ان‌ای و ATP.'],['سولفور','در ساخت بعضی آمینواسیدها و ویتامین‌ها مطرح است.'],
 ['فسفر','در نوکلئیک‌اسیدها، فسفولیپید و ATP.'],
 ['عناصر موردنیاز در مقدار کم','جزوه آهن، پتاسیم، منیزیم، کلسیم، مس و روی را در بحث کوفاکتور/عناصر ذکر می‌کند.'],
 ['سیدروفور ','ترکیب جذب‌کنندهٔ آهن؛ رقابت برای آهن میزبان می‌تواند به بیماری‌زایی کمک کند.'],
 ['انرژی','فتوهتروتروف: انرژی نور؛ کموهتروتروف: انرژی مواد آلی در توضیح جزوه. بسیاری از پاتوژن‌ها در گروه دوم مطرح‌اند.'],
 ['شرایط فیزیکی و گازی','دما، pH و نیاز به اکسیژن نیز برای رشد اهمیت دارند.']])+
 table(['مسیر','گیرندهٔ نهایی در شرح جزوه','تأمین انرژی / مکان'],[
 ['تنفس هوازی','O₂','الکترون‌ها در زنجیرهٔ انتقال الکترونِ غشای سیتوپلاسمی جابه‌جا می‌شوند و ATP با فسفریلاسیون اکسیداتیو تولید می‌شود.'],
 ['تنفس بی‌هوازی','ماده‌ای غیر از O₂، مثل نیترات یا ترکیبات سولفور.','نوعی تنفس؛ نبود اکسیژن آن را به‌خودی‌خود تخمیر نمی‌کند.'],
 ['تخمیر','در شرح کلی جزوه یک مادهٔ آلی، نه O₂.','فسفریلاسیون در سطح سوبسترا؛ در سیتوزول. در بی‌هوازی‌های اجباری و اختیاری مطرح شده است.']]),
 '«هترو» در این بحث به منبع کربن آلی کمک می‌کند؛ «فتو» به انرژی نور اشاره دارد. اکسیژن نداشتن به‌تنهایی نام یک مسیر متابولیک را تعیین نمی‌کند.',
 [q('اتوتروف و هتروتروف چه تفاوتی دارند و این تفاوت با فتو/کمو چه فرقی دارد؟','اتوتروف/هتروتروف دربارهٔ منبع کربن‌اند؛ CO₂ در برابر مواد آلی. فتو/کمو دربارهٔ منبع انرژی‌اند؛ نور در برابر انرژی شیمیایی در چارچوب توضیح جزوه.',['کربن از انرژی جداست','CO₂ و مواد آلی','نور و انرژی شیمیایی'],[15]),
 q('تنفس هوازی، تنفس بی‌هوازی و تخمیر را مقایسه کنید.','در هوازی گیرندهٔ نهایی O₂ است؛ در تنفس بی‌هوازی گیرندهٔ دیگری مثل نیترات مطرح است؛ تخمیر با فسفریلاسیون سطح سوبسترا و گیرندهٔ آلی در سیتوزول توضیح داده می‌شود.',['گیرندهٔ نهایی','مسیر تأمین انرژی','محل تخمیر'],[16]),
 q('چرا سیدروفور می‌تواند به پاتوژنز کمک کند؟','با جذب رقابتی آهن از میزبان دسترسی باکتری به عنصر لازم برای فعالیت و رشد را افزایش می‌دهد.',['جذب آهن','رقابت با میزبان','کمک به رشد/بیماری‌زایی'],[15])],
 ['برای کربن و انرژی دو ستون جدا می‌نویسم.','تفاوت سه مسیر را بدون حفظ‌کردن مثال نامطمئن بیان می‌کنم.'])

lesson(2,'واژه‌های ژنتیک و عناصر متحرک',[16,17],
 'ژنوم مجموعهٔ اطلاعات ژنتیکی سلول است و هر ژن بخشی از این مجموعه را تشکیل می‌دهد. پلاسمید، فاژ و ترنسپوزون می‌توانند در انتقال یا جابه‌جایی ژن‌های مقاومت و بیماری‌زایی نقش داشته باشند.',
 ['ژنوم، ژن و نوکلئوتید را تعریف کنم.','دی‌ان‌ای و آر‌ان‌ای را در سه محور مقایسه کنم.','پلاسمید، فاژ و ترنسپوزون را تفکیک کنم.'],
 table(['واژه','معنا'],[['ژنوم','کل مادهٔ ژنتیکی سلول؛ شامل اجزای کروموزومی و خارج‌کروموزومی در تعریف جزوه.'],['ژن','توالی دی‌ان‌ای که اطلاعات ساخت یک محصول کارکردی، مانند پروتئین یا آر‌ان‌ای، را در خود دارد.'],['نوکلئوتید','باز نیتروژنی + قند پنج‌کربنه + گروه فسفات.']])+
 table(['محور','دی‌ان‌ای','آر‌ان‌ای'],[['قند','دئوکسی‌ریبوز','ریبوز'],['باز متمایز','تیمین','یوراسیل به جای تیمین'],['وضعیت معمول در این بحث','دورشته‌ای','تک‌رشته‌ای']])+
 table(['عنصر','ویژگی','رابطه با مقاومت/بقا'],[
 ['پلاسمید','معمولاً حلقوی؛ همانندسازی مستقل؛ خارج‌کروموزومی و غیرالزامی.','می‌تواند ژن مقاومت حمل کند و با انتقال آن، باکتری دیگری ویژگی مقاومت پیدا کند.'],
 ['باکتریوفاژ','ویروس باکتری؛ در چرخهٔ لیتیک با لیز همراه است؛ در لیزوژنیک مادهٔ ژنتیکی در ارتباط با ژنوم میزبان باقی می‌ماند.','در انتقال ژنتیکی توسط فاژ نقش دارد.'],
 ['ترنسپوزون','عنصر ژنتیکی متحرک؛ شکل صفحهٔ ۱۷ نواحی IS و ژن ترانسپوزاز را نشان می‌دهد.','ژن مقاومت می‌تواند روی این عناصر هم باشد؛ جابه‌جایی بین زمینه‌های ژنتیکی مثل کروموزوم و پلاسمید مطرح است.']])+
 '<p>جزوه برای بسیاری از باکتری‌ها یک کروموزوم و برای E. coli حدود چهار میلیون جفت‌باز بیان می‌کند. این‌ها توصیف کلی و عدد تقریبی همین منبع‌اند، نه تعریف همهٔ باکتری‌ها.</p>',
 'پلاسمید = دی‌ان‌ای مستقل؛ فاژ = ویروس باکتری؛ ترنسپوزون = قطعهٔ متحرک. «حامل ژن» با «روش انتقال ژن» فرق دارد.',
 [q('نوکلئوتید از چه اجزایی ساخته شده و دی‌ان‌ای و آر‌ان‌ای چه تفاوت‌هایی دارند؟','نوکلئوتید از باز، قند پنج‌کربنه و فسفات ساخته شده است. دی‌ان‌ای دئوکسی‌ریبوز و تیمین دارد؛ آر‌ان‌ای ریبوز و یوراسیل. در این بحث دی‌ان‌ای دورشته‌ای و آر‌ان‌ای معمولاً تک‌رشته‌ای است.',['سه جزء','قندها','تیمین/یوراسیل','رشته‌ها'],[16]),
 q('چرخهٔ لیتیک و لیزوژنیک فاژ را مقایسه کنید.','در لیتیک تکثیر فاژ با لیز باکتری ارتباط دارد؛ در لیزوژنیک مادهٔ ژنتیکی فاژ در ارتباط با ژنوم میزبان باقی می‌ماند و ممکن است در نسل‌های بعد حفظ شود.',['لیز در لیتیک','ماندگاری ژنتیکی در لیزوژنیک'],[16]),
 q('چرا بررسی مقاومت فقط روی کروموزوم کافی نیست؟','ژن‌های مقاومت می‌توانند روی پلاسمید و ترنسپوزون نیز قرار داشته باشند؛ جزوه انتقال و جابه‌جایی این عناصر را در گسترش مقاومت مطرح می‌کند.',['کروموزوم تنها محل نیست','پلاسمید','ترنسپوزون'],[16,17])],
 ['سه عنصر ژنتیکی را در یک جمله برای هرکدام تعریف می‌کنم.','اجزای یک نوکلئوتید را رسم می‌کنم.'])

lesson(2,'از همانندسازی تا جهش و انتقال ژن',[10,17,18],
 'همانندسازی، دی‌ان‌ای را تکثیر می‌کند؛ رونویسی از آن آر‌ان‌ای می‌سازد و ترجمه به ساخت پروتئین می‌انجامد. جهش، توالی را تغییر می‌دهد و انتقال افقی، دی‌ان‌ای را میان باکتری‌ها جابه‌جا می‌کند.',
 ['سه فرایند را با ورودی و خروجی بنویسم.','چهار نوع جهش را از هم تشخیص دهم.','سه راه انتقال ژنتیکی را با واسطهٔ هرکدام مقایسه کنم.'],
 table(['فرایند','ورودی ← خروجی','اجزای مهم در جزوه'],[
 ['همانندسازی',en('دی‌ان‌ای ← دی‌ان‌ای'),'نیمه‌حفاظتی: در هر محصول یک رشتهٔ قدیمی و یک رشتهٔ جدید؛ همانندسازی دوطرفه مطرح است.'],
 ['رونویسی',en('دی‌ان‌ای ← آر‌ان‌ای'),'در این بخش آر‌ان‌ای پیام‌رسان و ۶۴ کدون ممکن مطرح شده‌اند.'],
 ['ترجمه',en('آر‌ان‌ای پیام‌رسان ← پروتئین'),'ریبوزوم 70S؛ آر‌ان‌ای ناقل حامل آنتی‌کدون.']])+
 '<h4>همانندسازی در چند گام</h4>'+steps(['هلیکاز دو رشته را باز می‌کند.','رشتهٔ جدید از انتهای ۵′ به انتهای ۳′ ساخته می‌شود.','یک رشته پیوسته و دیگری به‌صورت قطعات اوکازاکی ساخته می‌شود.','لیگاز قطعات را به هم وصل می‌کند؛ محصول نیمه‌حفاظتی است.'])+
 '<p>جهش تغییر توالی نوکلئوتیدی دی‌ان‌ای است. برای باکتری می‌تواند مفید (مثلاً مزیت مقاومت)، مضر یا کشنده باشد؛ پیامد به محل و نقش ژن بستگی دارد. جهش خودبه‌خودی یا القایی مطرح است. جزوه UV و تشکیل دیمر تیمین را مثال می‌زند و تأکید می‌کند تابش می‌تواند علاوه بر کشتن، جهش ایجاد کند.</p>'+
 table(['نوع','تغییر اصلی','پیامد برای پروتئین'],[
 [en('خاموش'),'کدون عوض می‌شود ولی همان آمینواسید را مشخص می‌کند.',en('UUU ← UUC')+'؛ هر دو فنیل‌آلانین در مثال جزوه.'],
 [en('دگرمعنا'),'کدون آمینواسید دیگری را مشخص می‌کند.','تغییر آمینواسید.'],
 [en('بی‌معنا'),'کدون به کدون پایان تبدیل می‌شود.','توقف زودتر و پروتئین ناقص.'],
 [en('تغییر چارچوب خواندن'),'درج یا حذف در ناحیهٔ رمزکننده، اگر تعداد نوکلئوتیدها مضرب سه نباشد، چارچوب خواندن را تغییر می‌دهد.','دسته‌بندی سه‌تاییِ کدون‌های پس از محل تغییر عوض می‌شود و ممکن است توالی پروتئین یا محل پایان ترجمه تغییر کند.']])+
 table(['راه انتقال','چه چیزی واسطه است؟','شرح ساده'],[
 [en('دریافت دی‌ان‌ای آزاد'),'دی‌ان‌ای آزاد در محیط','دریافت دی‌ان‌ای آزاد از محیط؛ دی‌ان‌ای دریافتی ممکن است در ژنوم ادغام شود یا به‌صورت پلاسمید باقی بماند.'],
 [en('انتقال با واسطهٔ فاژ'),'باکتریوفاژ','فاژ واسطهٔ انتقال ژن است.'],
 [en('انتقال تماسی (هم‌یوغی)'),'تماس سلولی و دستگاه انتقال/پیلی جنسی در شرح جزوه','دی‌ان‌ای از دهندهٔ F⁺ به گیرندهٔ F⁻ منتقل می‌شود؛ در مثال پلاسمید، نسخهٔ دریافتی تکمیل و همانندسازی می‌شود.']]),
 'برای جهش: «همان آمینواسید / آمینواسید دیگر / پایان / فریم». برای انتقال: «آزاد / فاژ / تماس». این دو فهرست پاسخ دو سؤال متفاوت‌اند.',
 [q('همانندسازی، رونویسی و ترجمه را با ورودی و خروجی مقایسه کنید.','همانندسازی دی‌ان‌ای را تکثیر می‌کند؛ رونویسی از دی‌ان‌ای، آر‌ان‌ای می‌سازد؛ ترجمه از آر‌ان‌ای پیام‌رسان با کمک ریبوزوم و آر‌ان‌ای ناقل، پروتئین می‌سازد.',['دی‌ان‌ای ← دی‌ان‌ای','دی‌ان‌ای ← آر‌ان‌ای','آر‌ان‌ای پیام‌رسان ← پروتئین','ریبوزوم و آر‌ان‌ای ناقل'],[17]),
 q('خاموش، دگرمعنا و بی‌معنا را تعریف کنید.','خاموش تغییر کدون بدون تغییر آمینواسید؛ دگرمعنا تغییر آمینواسید؛ بی‌معنا ایجاد کدون پایان و توقف زودرس است.',['نوع تغییر در هرکدام','پیامد برای پروتئین'],[18]),
 q('سه روش انتقال ژنتیکی را بر اساس واسطهٔ انتقال مقایسه کنید.','ترانسفورماسیون، دریافت دی‌ان‌ای آزاد از محیط است. ترانسداکشن با واسطهٔ فاژ انجام می‌شود. کونژوگاسیون یا هم‌یوغی، انتقال دی‌ان‌ای از دهنده به گیرنده از راه تماس سلولی و دستگاه انتقال است.',['دی‌ان‌ای آزاد','فاژ','تماس و دهنده/گیرنده'],[18])],
 ['سه فرایند و سه راه انتقال را در دو جدول جدا می‌نویسم.','جهش پایان را با جهش خاموش اشتباه نمی‌گیرم.'])

lesson(3,'استرپتوکوک‌ها: از ویژگی تا مسیر تشخیص',[20,21,27],
 'برای افتراق کوکسی‌های گرم مثبت، از آرایش سلول‌ها و کاتالاز شروع می‌کنیم و سپس همولیز و آزمون‌های اختصاصی‌تر را می‌سنجیم. هر آزمون، بخشی از مسیر شناسایی را روشن می‌کند.',
 ['ویژگی‌های عمومی مطرح‌شده را نام ببرم.','کاتالاز، همولیز و لنسفیلد را جدا کنم.','مسیر افتراق استاف و استرپ را بنویسم.'],
 '<p>استرپتوکوک‌ها کوکسی گرم مثبت، معمولاً زنجیره‌ای، کاتالاز منفی، فاقد اسپور و حرکت و بی‌هوازی اختیاری معرفی می‌شوند. کپسول و آرایش دقیق را باید در سطح گونه هم بررسی کرد.</p>'+
 table(['آزمایش/معیار','چه چیزی را بررسی می‌کند؟','نتیجه در چارچوب جزوه'],[
 ['کاتالاز','افزودن H₂O₂ و مشاهدهٔ حباب.','مثبت: مسیر استاف؛ منفی: مسیر استرپ. این مسیر آموزشی را به شناسایی همهٔ کوکسی‌ها تعمیم نده.'],
 ['همولیز روی آگار خون‌دار','تغییر محیط اطراف کلنی.','بتا: هالهٔ شفاف/همولیز کامل؛ آلفا: سبزی/همولیز ناقص؛ گاما: نبود همولیز.'],
 ['لنسفیلد ','کربوهیدرات C دیواره.','گروه‌های A، B، C، D مطرح‌اند؛ پنوموکوک در این تقسیم‌بندی قرار نمی‌گیرد.'],
 ['دیسک باسیتراسین','هالهٔ عدم رشد اطراف دیسک.','در افتراق درسی A و B: پایوژنز حساس؛ آگالاکتیه مقاوم.']])+
 table(['الگوی همولیز در متن','مثال جزوه'],[['بتا','پایوژنز و آگالاکتیه'],['آلفا','پنوموکوک و بسیاری از ویریدانس‌ها؛ بعضی ویریدانس‌ها بدون همولیزند.'],['گاما','بسیاری از انتروکوک‌ها؛ الگوی همولیز در همهٔ گونه‌ها یکسان نیست.']])+
 '<h4>مسیر تشخیص مقایسه‌ای صفحهٔ ۲۷</h4>'+steps(['کوکسی گرم مثبت را بررسی کن؛ هر دو گروه استاف و استرپ در جزوه فاقد اسپور و حرکت‌اند.','اگر کاتالاز مثبت: کواگولاز را بررسی کن؛ مثبت در مسیر جزوه به S. aureus می‌رسد.','اگر کواگولاز منفی: نووبیوسین در مثال‌های جزوه؛ حساس ← S. epidermidis (فلور پوست)، مقاوم ← S. saprophyticus (عفونت ادراری زنان جوان).','اگر کاتالاز منفی: به مسیر همولیز برو؛ بتا سپس باسیتراسین برای افتراق پایوژنز/آگالاکتیه در مثال این درس.'])+
 '<p>«خوشه‌ای در برابر زنجیره‌ای» توصیف آرایش سلول‌ها زیر میکروسکوپ است. جزوه گاهی آن را زیر عنوان شکل کلنی می‌آورد؛ برای پاسخ نوشتاری، آرایش سلول را از شکل کلنی کشت جدا بنویس.</p>',
 'هر آزمایش یک سؤال دارد: کاتالاز = حباب؟ همولیز = چه هاله‌ای؟ باسیتراسین = رشد دور دیسک؟ لنسفیلد = کربوهیدرات دیواره؟',
 [q('آلفا، بتا و گاما همولیز را با ظاهر محیط و یک مثال مقایسه کنید.','آلفا: هالهٔ سبز مثل پنوموکوک؛ بتا: هالهٔ شفاف ناشی از همولیز کامل، مثل پایوژنز؛ گاما: نبود همولیز، مثل انتروکوک در مثال این منبع.',['ظاهر سه حالت','سه مثال با قید منبع'],[20]),
 q('استاف و استرپ در چه چیزهایی شبیه و در چه چیزهایی متفاوت‌اند؟','هر دو کوکسی گرم مثبت و فاقد اسپور و حرکت‌اند. استاف معمولاً خوشه‌ای و کاتالاز مثبت، استرپ معمولاً زنجیره‌ای و کاتالاز منفی است.',['شباهت‌ها','آرایش سلولی','کاتالاز'],[27]),
 q('مبنای گروه‌بندی لنسفیلد چیست؟ A و B به کدام مثال‌ها مربوط‌اند؟','مبنای ذکرشده کربوهیدرات C دیواره است؛ A با پایوژنز و B با آگالاکتیه در این درس ارتباط دارند. پنوموکوک در این گروه‌بندی جای نمی‌گیرد.',['کربوهیدرات C','A/پایوژنز','B/آگالاکتیه','استثنای پنوموکوک'],[21,27])],
 ['مسیر کاتالاز تا آزمایش افتراقی را بدون نگاه رسم می‌کنم.','کپسول را ویژگی همگانی استرپتوکوک‌ها نمی‌نویسم.'])

lesson(3,'پایوژنز: چرک، سم و عارضهٔ ایمنی',[21,22,23,24,33],
 'استرپتوکوک پایوژنز از سه راه بیماری ایجاد می‌کند: عفونت مستقیم بافت، اثر سم‌ها و عوارض ایمنی پس از عفونت. شناخت این سه سازوکار، حفظ بیماری‌ها را آسان‌تر می‌کند.',
 ['ویژگی‌های شناسایی و عوامل بیماری‌زایی را توضیح دهم.','بیماری‌های پوستی را با عمق و ظاهر مقایسه کنم.','تب روماتیسمی را از گلومرولونفریت افتراق دهم.'],
 '<p><strong>'+en('Streptococcus pyogenes')+'</strong> در جزوه گروه A، بتاهمولیتیک، حساس به باسیتراسین و بی‌هوازی اختیاری است. نام پایوژنز با تولید چرک ارتباط داده شده است. دیوارهٔ گرم مثبت و کپسول هیالورونیک دارد.</p>'+
 table(['عامل بیماری‌زایی','کارکرد'],[
 ['کپسول','کمک به مقابله با فاگوسیتوز و بقا.'],['لیپوتیکوئیک اسید و پروتئین M','اتصال و مشارکت در بیماری‌زایی؛ M در بحث عارضهٔ ایمنی هم مطرح است.'],
 ['هیالورونیداز','تجزیهٔ هیالورونیک اسید بافت همبند و کمک به گسترش.'],['استرپتوکیناز','از بین بردن لخته/فیبرین و تسهیل گسترش.'],
 ['استرپتولیزین S و O','S با بتاهمولیز؛ O با سنجش آنتی‌بادی برای بررسی مطرح شده است.'],['اگزوتوکسین‌های پایروژنیک','تب، التهاب و بیماری‌های سمی.']])+
 '<p>محل کلونیزاسیون مطرح‌شده پوست و مخاط حلق است. حضور در همان محل می‌تواند بیماری موضعی بسازد؛ انتشار از خون می‌تواند اندام‌های دیگر را درگیر کند. خطر با ضعف ایمنی، سن خیلی کم یا زیاد، بیماری زمینه‌ای، HIV، سرطان، پیوند و داروهای سرکوب ایمنی بیشتر می‌شود.</p>'+
 table(['بیماری','آنچه برای پاسخ تشریحی لازم است'],[
 ['فارنژیت / التهاب لوزه','گلودرد، تب، تورم لوزه، لکوسیتوز، التهاب و چرک در حلق در جزوه.'],
 ['تب مخملک ','گلودرد و اثر سم؛ راش ابتدا تنه و سپس اندام‌ها، زبان توت‌فرنگی. تصاویر صفحهٔ ۲۲ راش، حلق و لوزه را نشان می‌دهند.'],
 ['زردزخم ','ضایعهٔ سطحی با ظاهر زرد اطراف صورت/دهان در تصاویر و شرح جزوه؛ ورود از خراش یا زخم مطرح است.'],
 ['بادسرخ ','درگیری درم/لنفاتیک، التهاب و قرمزی با مرز مشخص‌تر نسبت به سلولیت.'],
 ['سلولیت ','گسترش به زیرجلد؛ مرز قرمزی کمتر مشخص و حال عمومی بدتر در مقایسهٔ جزوه.'],
 ['فاسیت نکروزان ','عفونت تخریب‌کنندهٔ بافت نرم/فاسیا در عنوان؛ جزوه پیشروی شدید و لقب گوشت‌خوار را توضیح می‌دهد.'],
 ['سایر عفونت‌های فهرست‌شده','عفونت زخم و سوختگی، گوش میانی، بافت نرم، تناسلی و در انتشار، درگیری اندام‌ها.'],
 ['سندروم شوک سمی','سم‌ها ← افت فشار و افزایش نفوذپذیری رگ ← ادم و کاهش خون‌رسانی ← آسیب اندام‌ها.']])+
 '<h4>دو عارضهٔ پس از عفونت</h4>'+table(['محور','تب روماتیسمی','گلومرولونفریت پس از استرپ'],[
 ['عفونت قبلی در جزوه','معمولاً گلودرد استرپتوکوکی','گلودرد یا عفونت پوستی'],
 ['مکانیسم','شباهت آنتی‌ژنی مرتبط با M و پاسخ ایمنی علیه بافت میزبان','رسوب کمپلکس آنتی‌ژن–آنتی‌بادی در گلومرول'],
 ['عضو هدف','قلب و مفاصل در شرح جزوه','کلیه و اختلال فیلتراسیون'],
 ['نکتهٔ مشترک','ناشی از پیامد ایمنی؛ با حضور مستقیم باکتری در بافت یکی نیست.','ناشی از پیامد ایمنی؛ با حضور مستقیم باکتری در بافت یکی نیست.']])+
 '<p><strong>تشخیص در چارچوب درس:</strong> نمونه از محل درگیر، کشت، رنگ گرم و آزمایش‌های تأییدی؛ روش‌های سرولوژی (آنتی‌ژن/آنتی‌بادی) و مولکولی مثل PCR هم ذکر شده‌اند. سنجش آنتی‌بادی علیه استرپتولیزین O در این زمینه مطرح است. در عارضهٔ پس از عفونت، کشت الزاماً نشان‌دهندهٔ حضور عامل در بافت آسیب‌دیده نیست.</p>'+
 '<details class="explanation"><summary>یادداشت درمان و واکسنِ همین جزوه</summary><div><p>جزوه برای پایوژنز واکسن موجود ذکر نمی‌کند و پنی‌سیلین G را درمان اصلی، با سفالوسپورین یا ماکرولید در شرایط ذکرشده معرفی می‌کند. برداشت بافت در فاسیت نکروزان و اهمیت رسیدگی به گلودرد هم مطرح‌اند. نکتهٔ این بخش، تفاوت حذف باکتری با کنترل آسیب بافتی و پیامد ایمنی است.</p></div></details>',
 'سه ستون: «خود باکتری / سم / ایمنی پس از عفونت». برای عوارض ایمنی: «M و قلب» در برابر «کمپلکس و کلیه».',
 [q('چهار عامل بیماری‌زایی پایوژنز را با عملکرد توضیح دهید.','کپسول به فرار از فاگوسیتوز کمک می‌کند؛ M و لیپوتیکوئیک اسید در اتصال نقش دارند؛ هیالورونیداز به گسترش در بافت و استرپتوکیناز به عبور از لخته/فیبرین کمک می‌کنند. سم‌های پایروژنیک هم در بیماری سمی‌اند.',['نام عامل','عملکرد متناظر','ساختار سطحی در برابر عامل ترشحی'],[21,22]),
 q('تب روماتیسمی و گلومرولونفریت را از نظر مکانیسم و عفونت قبلی مقایسه کنید.','در تب روماتیسمی شباهت آنتی‌ژنی مرتبط با M و حملهٔ ایمنی به بافت میزبان مطرح است؛ در گلومرولونفریت رسوب کمپلکس‌های ایمنی در کلیه. اولی معمولاً پس از گلودرد، دومی پس از گلودرد یا عفونت پوست در جزوه مطرح است.',['شباهت آنتی‌ژنی','رسوب کمپلکس','قلب در برابر کلیه','عفونت قبلی'],[23,24,33]),
 q('بادسرخ، سلولیت و فاسیت نکروزان را مقایسه کنید.','بادسرخ درم و لنفاتیک را با قرمزی محدودتر درگیر می‌کند؛ سلولیت زیرجلد را با مرز کمتر مشخص؛ فاسیت نکروزان با تخریب شدید بافت و پیشروی خطرناک مطرح است.',['محل/عمق','مرز ضایعه','تخریب و شدت'],[23]),
 q('چگونه سم‌ها در سندروم شوک سمی به آسیب اندام می‌رسند؟','جزوه ورود سم‌ها به خون، افزایش نفوذپذیری عروقی و افت فشار را به ادم و کاهش خون‌رسانی و سپس آسیب اندام مرتبط می‌کند.',['سم','نفوذپذیری/فشار','ادم و کاهش خون‌رسانی','آسیب اندام'],[24])],
 ['عفونت فعال، سمی و عارضهٔ ایمنی را جدا می‌نویسم.','برای هر عامل بیماری‌زایی یک فعل اختصاصی می‌آورم.'])

lesson(3,'آگالاکتیه و آزمایش کمپ',[25,28],
 'استرپتوکوک آگالاکتیه همان استرپتوکوک گروه B است. آزمون CAMP به شناسایی آن کمک می‌کند و اهمیت بالینی‌اش به‌ویژه در عفونت‌های مادر و نوزاد است.',
 ['افتراق درسی گروه A و B را بنویسم.','مراحل و نتیجهٔ کمپ را توضیح دهم.','ارتباط کلونیزاسیون مادر و عفونت نوزاد را بیان کنم.'],
 '<p><strong>'+en('Streptococcus agalactiae')+'</strong> گروه B، بتاهمولیتیک، کپسول‌دار، بی‌هوازی اختیاری و مقاوم به باسیتراسین است. از عفونت پستان گاو و کاهش شیر نام گرفته و بعد در انسان نیز مطرح شده است.</p>'+
 '<h4>آزمون CAMP چه چیزی را نشان می‌دهد؟</h4>'+steps(['محیط آگار خون‌دار برای مشاهدهٔ همولیز آماده می‌شود.','S. aureus به‌صورت یک خط و نمونهٔ مشکوک به‌صورت عمود بر آن کشت داده می‌شود.','در جزوه انکوباسیون حدود ۲۴ ساعت در ۳۷ درجه آمده است.','همولیز تقویت‌شده به شکل سر پیکان کنار محل نزدیک‌شدن خطوط به نفع آگالاکتیه در مسیر درسی است.','عامل کمپ با تقویت همولیز همراه است؛ ظاهر سر پیکان نکتهٔ اصلی تصویر صفحهٔ ۲۵ است.'])+
 '<p>برای پاسخ سؤال کمپ، فقط «مثبت است» کافی نیست؛ محیط، باکتری همراه، آرایش کشت، ظاهر نتیجه و تفسیر را بنویس. جزوه صریحاً این آزمایش را «مهم و سؤال‌ساز» نامیده است؛ این تأکید منبع است و پیش‌بینی مستقل امتحان نیست.</p>'+
 table(['محور مادر–نوزاد','شرح جزوه'],[
 ['محل حضور','دستگاه ادراری–تناسلی، واژن/رکتوم و مجرای گوارش.'],['مادر','حمل بدون بیماری را از عفونت تفکیک کن؛ سیستیت و عفونت صعودی در جزوه آمده‌اند.'],
 ['بارداری','درگیری پرده‌های اطراف جنین/کوریوآمنیونیت؛ پارگی زودرس پرده‌ها، زایمان زودرس، سقط یا مرگ داخل رحمی در فهرست منبع.'],
 ['نوزاد','درگیری ریه، باکتریمی/سپسیس و عبور به مایع مغزی‌نخاعی و مننژیت در توضیح جزوه.'],
 ['پیشگیریِ مطرح‌شده','شناسایی حمل گروه B در بارداری و پیشگیری متناسب با خطر انتقال هنگام زایمان، دو موضوع مرتبط این بخش‌اند.']]),
 'A = پایوژنز و باسیتراسین حساس؛ B = آگالاکتیه و باسیتراسین مقاوم، کمپ و مادر–نوزاد. این یک مقایسهٔ درسی است، نه جایگزین همهٔ آزمایش‌ها.',
 [q('آزمایش کمپ را از روش اجرا تا تفسیر توضیح دهید.','روی آگار خون‌دار استاف اورئوس خطی و نمونهٔ استرپ عمود بر آن کشت می‌شود. طبق جزوه پس از حدود ۲۴ ساعت در ۳۷ درجه، همولیز تقویت‌شدهٔ سرپیکانی به نفع آگالاکتیه است و به عامل کمپ ارتباط دارد.',['آگار خون‌دار','S. aureus','کشت عمود','سر پیکان','تفسیر و عامل'],[25]),
 q('پایوژنز و آگالاکتیه را با گروه، همولیز و باسیتراسین مقایسه کنید.','پایوژنز گروه A و آگالاکتیه گروه B است؛ هر دو در این درس بتاهمولیتیک‌اند؛ پایوژنز به باسیتراسین حساس و آگالاکتیه مقاوم است. کمپ برای آگالاکتیه مطرح است.',['A/B','بتا در هر دو','حساس/مقاوم','کمپ'],[20,21,25]),
 q('چرا آگالاکتیه در بحث مادر و نوزاد مهم است؟','می‌تواند در واژن/رکتوم یا دستگاه ادراری–تناسلی مادر حضور داشته باشد و با عفونت‌های بارداری یا انتقال به نوزاد ارتباط پیدا کند. سپسیس و مننژیت نوزادی از پیامدهای مطرح‌شده‌اند.',['محل کلونیزاسیون','ارتباط با بارداری/نوزاد','سپسیس و مننژیت'],[25,28])],
 ['کمپ را با پنج جزء پاسخ می‌دهم.','کلونیزاسیون مادر را به خودی خود بیماری نمی‌نامم.'])

lesson(4,'پنوموکوک: کپسول، انتشار و تشخیص',[28,29,30,32,33,35],
 'کپسول، ویژگی اصلی بیماری‌زایی پنوموکوک است. شکل دیپلوکوک نیزه‌ای، حساسیت به اپتوچین و حل‌شدن در صفرا، سرنخ‌های مهم افتراق آن از ویریدانس‌اند.',
 ['کلونیزاسیون را از بیماری تفکیک کنم.','دو مسیر انتشار و نقش کپسول/طحال را توضیح دهم.','آزمایش‌های افتراق و مادهٔ واکسن را نام ببرم.'],
 '<p><strong>'+en('Streptococcus pneumoniae')+'</strong> کوکسی گرم مثبت و کاتالاز منفی با نمای معمول دیپلوکوک نیزه‌ای/شعلهٔ شمع است؛ جفت یا زنجیرهٔ کوتاه ممکن است دیده شود. در محیط کشت معمول درس آلفاهمولیتیک مطرح است. جزوه آن را از عوامل مهم پنومونی اکتسابی از جامعه می‌داند.</p>'+
 '<p>پنوموکوک می‌تواند بدون ایجاد علامت در <strong>نازوفارنکس</strong> حمل شود. گسترش به گوش، سینوس یا ریه، و ورود به خون، مسیرهای متفاوت بیماری را ایجاد می‌کنند.</p>'+
 table(['مسیر','پیامدها در منبع'],[
 ['انتشار موضعی','گوش میانی ← اوتیت؛ سینوس ← سینوزیت؛ ورود به ریه با آسپیراسیون ← پنومونی.'],
 ['تهاجمی '+en('تهاجمی'),'ورود به خون/باکتریمی و سپس درگیری مغز (مننژیت)، قلب (اندوکاردیت)، شکم (پریتونیت) یا مفصل.']])+
 '<p>پیشرفت پنومونی در توضیح جزوه: تجمع باکتری، ماکروفاژ و ترشحات در برونشیول/آلوئول ← اختلال تبادل گاز ← احتمال ورود از مویرگ به خون.</p>'+
 table(['عامل','چرا مهم است؟'],[
 ['کپسول','فاکتور اصلی بیماری‌زایی در جزوه؛ کمک به فرار از ایمنی و فاگوسیتوز و اتصال، بیوفیلم و کاهش دسترسی دارو.'],
 ['IgA protease','کاهش اثر IgA ترشحی در سطح مخاط.'],
 ['ترکیبات دیواره و پروتئین‌های چسبنده','تیکوئیک اسید، پپتیدوگلیکان و پروتئین‌های اتصال در فهرست منبع.'],
 ['طحال','در مقابله با باکتری‌های کپسول‌دار نقش دارد؛ نبود طحال یکی از عوامل مستعدکنندهٔ ذکرشده است.']])+
 '<p>دیگر زمینه‌های حساسیت: سن خیلی پایین یا بالا، HIV، دیابت، سرطان/شیمی‌درمانی، پیوند، سرکوب ایمنی، بیماری مزمن، اختلال مژک‌های تنفسی، مشکلات گردش خون و مصرف الکل/مواد مخدر در جزوه. این فهرست توضیح زمینه است، نه شرط لازم برای هر بیماری.</p>'+
 table(['مرحلهٔ تشخیص','توضیح'],[
 ['نمونه','پنومونی: خلط/ترشحات ریوی؛ انتشار خونی: خون؛ درگیری دستگاه عصبی مرکزی: مایع مغزی‌نخاعی در شرح جزوه.'],
 ['کشت','محیط غنی‌شده مانند آگار خون‌دار یا آگار شکلاتی؛ کلنی ریز و آلفاهمولیتیک در توضیح درس.'],
 ['آزمون‌های پایه','رنگ گرم، شکل و کاتالاز.'],
 ['اپتوچین','پنوموکوک حساس؛ هالهٔ عدم رشد اطراف دیسک.'],
 ['آزمون حلالیت در صفرا','لیز/حل‌شدن در حضور صفرا؛ مثبت در جدول پنوموکوک.'],
 ['آزمون تورم کپسولی (کوئلونگ)','آنتی‌سرم علیه کپسول + نمونه؛ مشاهدهٔ تورم/برجسته‌شدن کپسول.'],
 ['مولکولی','PCR به‌عنوان روش دیگر ذکر شده است.']])+
 '<details class="explanation"><summary>جزئیات جدول مقایسهٔ صفحهٔ ۳۳</summary><div>'+table(['ویژگی در جدول جزوه','پنوموکوک','ویریدانس'],[
 ['شکل','نیزه‌ای/شعلهٔ شمع','گرد/بیضی'],['آرایش','جفت','زنجیرهٔ بلند'],['کپسول','حاضر','غایب در جدول'],
 ['کلنی آگار خون‌دار','کلنی با مرکز فرورفته، شبیه سکه','محدب'],['محیط مایع','کدورت یکنواخت','کدورت دانه‌دانه'],
 ['صفرا','محلول','نامحلول'],['تخمیر اینولین','مثبت','منفی'],['اپتوچین','حساس','مقاوم'],['بیماری‌زایی در موش','مثبت','منفی در جدول'],
 ['آزمون تورم کپسولی (کوئلونگ)','مثبت','منفی'],['همولیز','آلفا در هوازی؛ بتا در بی‌هوازی طبق جدول','آلفا یا بدون همولیز طبق جدول'],['بیماری شاخص','پنومونی','عفونت‌های دهانی در جدول']])+ '<p>در افتراق معمول، اپتوچین و حلالیت در صفرا از نکات کلیدی‌اند. بعضی ویژگی‌ها مانند کپسول یا آرایش سلول در همهٔ اعضای یک گروه یکسان نیستند.</p></div></details>'+
 '<details class="explanation"><summary>چرا کپسول در واکسن اهمیت دارد؟</summary><div><p>آنتی‌ژن‌های پلی‌ساکاریدی کپسول، پایهٔ واکسن‌های پنوموکوکی‌اند. در واکسن کونژوگه، پلی‌ساکارید به یک پروتئین حامل متصل می‌شود تا پاسخ ایمنی مؤثرتری ایجاد شود. عدد ظرفیت واکسن، تعداد سروتیپ‌های پوشش‌داده‌شده را بیان می‌کند.</p></div></details>',
 'پنوموکوک: «جفت نیزه‌ای + کپسول + اپتوچین حساس + صفرا محلول». در سؤال بیماری، مسیر موضعی و خونی را جدا بنویس.',
 [q('چرا نبود طحال با خطر پنوموکوک ارتباط دارد؟','طحال در مقابله با باکتری‌های کپسول‌دار مهم است؛ پنوموکوک کپسول دارد و کپسول به فرار از ایمنی کمک می‌کند. بنابراین نبود طحال یکی از زمینه‌های حساسیت است.',['کپسول','نقش طحال','کاهش دفاع'],[28,29]),
 q('اپتوچین، صفرا و آزمون تورم کپسولی (کوئلونگ) برای پنوموکوک چه نتیجه‌ای دارند؟','حساس به اپتوچین؛ حل‌شدن/لیز در صفرا؛ آزمون تورم کپسولی (کوئلونگ) مثبت با آنتی‌سرم علیه کپسول.',['حساسیت و هاله','آزمون حلالیت در صفرا مثبت','آنتی‌سرم و کپسول'],[29,30,33]),
 q('انتشار موضعی پنوموکوک را با بیماری تهاجمی مقایسه کنید.','موضعی از نازوفارنکس به گوش، سینوس یا ریه می‌رود؛ تهاجمی وارد خون می‌شود و می‌تواند به اندام‌هایی مثل مغز، قلب و مفصل برسد.',['نازوفارنکس','گوش/سینوس/ریه','خون و اندام‌های دور'],[28,29])],
 ['با نتیجهٔ سه آزمایش اصلی پنوموکوک را از ویریدانس جدا می‌کنم.','در پاسخ واکسن، مادهٔ کپسولی را از تعداد تیپ‌ها جدا می‌نویسم.'])

lesson(4,'ویریدانس، موتانس و میتیس: از پلاک تا بیماری',[30,31,32,33,35],
 'استرپتوکوک‌های ویریدانس بخشی از میکروبیوتای دهان‌اند. بعضی در ساخت پلاک و پوسیدگی نقش دارند و ورودشان به خون می‌تواند در فرد مستعد به اندوکاردیت بینجامد.',
 ['گروه ویریدانس و اعضای ذکرشده را نام ببرم.','سه شرط نقش باکتری در پوسیدگی را توضیح دهم.','میتیس را از پنوموکوک با آزمایش افتراقی جدا کنم.'],
 '<p>ویریدانس در جزوه گروهی از استرپتوکوک‌های دهانی، گرم مثبت، کاتالاز منفی، بدون اسپور و حرکت و بی‌هوازی اختیاری معرفی شده است. نام آن با رنگ سبز همولیز آلفا ارتباط داده می‌شود. «گروه» را با یک گونهٔ واحد یکی نکن.</p>'+
 table(['عضو ذکرشده','نکتهٔ اختصاصی موجود در همین فایل'],[
 [en('S. mutans'),'در بحث دهان، پوسیدگی و تأکید امتحانی جزوه مطرح است.'],
 [en('S. mitis'),'عفونت دهانی و اندوکاردیت تحت‌حاد در منبع؛ افتراق از پنوموکوک با اپتوچین.'],
 [en('S. sanguinis'),'از اعضای فهرست‌شده؛ جزوه جزئیات اختصاصی بیشتری در این بخش نمی‌دهد.'],
 [en('S. salivarius'),'پس از موتانس/میتیس در بحث اهمیت دهانی نام برده شده است.'],
 [en('S. anginosus'),'با آبسه ارتباط داده شده است.']])+
 '<h4>ساخت بیوفیلم و پوسیدگی</h4>'+steps(['باکتری‌ها به سطح دندان متصل و کلونیزه می‌شوند.','در حضور ساکارز، پلی‌ساکاریدهای خارج‌سلولی/گلوکان در شبکهٔ چسبندهٔ شرح جزوه مطرح‌اند.','مولکول‌های چسبندگی و پروتئین‌های متصل‌شونده به گلوکان به اتصال باکتری‌ها به هم و به سطح کمک می‌کنند.','تجمع باکتری + مواد ترشحی ← بیوفیلم و پلاک.','تجزیهٔ کربوهیدرات و تولید اسید، pH پلاک را کاهش می‌دهد و به خروج مواد معدنی از بافت دندان می‌انجامد.','آسیب از مینا به عاج و در ادامه به بخش‌های عمقی دندان می‌رود.'])+
 '<p><strong>سه شرط نقش در پوسیدگی:</strong> توان ساخت بیوفیلم، تحمل فضای اسیدی و مصرف کربوهیدرات با تولید اسید. برای سؤال مکانیسم، صرف گفتن «باکتری زیاد می‌شود» کافی نیست؛ اتصال، ماتریکس، قند، اسید و از دست رفتن مواد معدنی را به هم وصل کن.</p>'+
 '<p><strong>مسیر التهابی جدا:</strong> تجمع پلاک در کنار لثه ← التهاب لثه '+'؛ پیشرفت به بافت‌های زیرین و استخوان و احتمال از دست رفتن دندان مطرح است. وجود بیوفیلم در حالت سالم هم گفته شده؛ تغییر ترکیب، بهداشت، رژیم قندی، وضعیت ایمنی و عوامل فردی با بیماری مرتبط‌اند.</p>'+
 '<h4>از دهان به خون</h4><p>ورود باکتری به خون با باکتریمی ارتباط دارد. جزوه برای افراد مستعد، به‌ویژه با مشکلات قلبی/دریچه، اندوکاردیت تحت‌حاد را مطرح می‌کند. محل حضور میکروب تعیین می‌کند که حمل طبیعی باشد یا زمینهٔ عفونت ایجاد شود.</p>'+
 '<p>افتراق اصلی میتیس/ویریدانس از پنوموکوک در این فایل: ویریدانس <strong>اپتوچین مقاوم و در صفرا نامحلول</strong>؛ پنوموکوک <strong>حساس و محلول</strong>. جزوه برای ویریدانس کپسول را غایب و برای پنوموکوک حاضر ثبت می‌کند؛ این نسبت را در چارچوب جدول منبع بخوان.</p>'+
 '<details class="explanation"><summary>اقدامات و داروهای ذکرشده در جزوه</summary><div><p>صفحهٔ ۳۲ بهداشت دهان، کاهش مصرف قند، مسواک و نخ دندان و دهان‌شویه را ذکر می‌کند؛ برای کلرهگزیدین احتمال تغییر رنگ دندان نوشته شده است. پنی‌سیلین و در مقاومت سفالوسپورین نسل سوم مثل سفتریاکسون در بحث درمان آمده‌اند. وجود باکتری دهانی به‌تنهایی در متن برای فرد سالم دلیل مصرف آنتی‌بیوتیک نیست؛ پیشگیری دارویی به نوع مداخله و وضعیت بیمار بستگی دارد.</p></div></details>',
 'سه ویژگی پوسیدگی: «می‌چسبد، اسید را تحمل می‌کند، اسید می‌سازد». برای افتراق پنوموکوک/ویریدانس: «حساس–محلول» در برابر «مقاوم–نامحلول».',
 [q('سه شرط نقش باکتری در پوسیدگی را نام ببرید و به مکانیسم وصل کنید.','ساخت بیوفیلم ماندگاری روی دندان را فراهم می‌کند؛ تحمل محیط اسیدی اجازهٔ بقا می‌دهد؛ مصرف کربوهیدرات و تولید اسید باعث از دست رفتن مواد معدنی می‌شود.',['بیوفیلم','تحمل اسید','تولید اسید','از دست رفتن مواد معدنی'],[31]),
 q('چگونه S. mitis را از پنوموکوک افتراق می‌دهیم؟','میتیس از ویریدانس است و به اپتوچین مقاوم و در صفرا نامحلول معرفی می‌شود؛ پنوموکوک حساس به اپتوچین و در صفرا محلول است. هر دو در بحث کوکسی گرم مثبت و کاتالاز منفی مطرح‌اند.',['شباهت پایه','اپتوچین','صفرا'],[32,33,35]),
 q('چرا باکتری طبیعی دهان می‌تواند با اندوکاردیت ارتباط پیدا کند؟','با ورود از دهان به جریان خون، محل حضور تغییر می‌کند. جزوه در میزبان مستعد، ورود ویریدانس به خون و اندوکاردیت تحت‌حاد را مطرح می‌کند.',['محل طبیعی در دهان','باکتریمی','میزبان مستعد و قلب'],[30,31,32])],
 ['مکانیسم پوسیدگی را با پنج واژهٔ کلیدی می‌نویسم.','می‌دانم ویریدانس‌ها می‌توانند آلفاهمولیتیک یا بدون همولیز باشند.'])

lesson(4,'گروه D و انتروکوک: خواندن فلوچارت',[33,34],
 'در مسیر شناسایی گروه D، آزمون صفرا–اسکولین و توان رشد در نمک به افتراق انتروکوک کمک می‌کنند. تحمل صفرا در این آزمون با حل‌شدن پنوموکوک در صفرا فرق دارد.',
 ['مسیر فلوچارت صفحهٔ ۳۴ را توضیح دهم.','انتروکوک را از گروه D غیرانتروکوکی در همین مسیر جدا کنم.','بیماری‌ها و زمینهٔ فرصت‌طلبی را نام ببرم.'],
 '<p>جزوه این گروه را در مسیر گاما/بدون همولیز مطرح می‌کند. برای انتروکوک تحمل نمک‌های صفراوی (تا ۴۰٪ در متن)، نمک ۶٫۵٪، pH بالا و حرارت بالا ذکر شده است. این اعداد توصیف همین منبع‌اند.</p>'+
 steps(['در فلوچارت، نمونهٔ بدون همولیز وارد آزمون صفرا–اسکولین می‌شود.','اگر آزمون صفرا–اسکولین منفی باشد: شاخهٔ استرپتوکوک‌های بدون همولیز در شکل.','اگر مثبت باشد: رشد در نمک ۶٫۵٪ بررسی می‌شود.','رشد در نمک (مثبت): گونه‌های انتروکوک در مسیر جزوه.','عدم رشد در نمک (منفی): گروه D غیرانتروکوکی در مسیر جزوه.'])+
 table(['دو آزمون با واژهٔ صفرا','تفاوت'],[['آزمون حلالیت در صفرا پنوموکوک','حل‌شدن/لیز شدن؛ برای افتراق پنوموکوک از ویریدانس.'],['آزمون صفرا–اسکولین در فلوچارت گروه D','آزمون مسیر شناسایی گروه D/انتروکوک؛ نتیجهٔ مثبت یا منفی آن به شاخهٔ بعدی هدایت می‌کند. جزوه شیمی دقیق این آزمایش را توضیح نداده است.']])+
 '<p>در منبع، انتروکوک‌ها در بیماران بستری با مصرف مداوم آنتی‌بیوتیک، افراد مستعد یا دارای اعضای مصنوعی بیشتر مطرح‌اند. بیماری‌های فهرست‌شده: اندوکاردیت تحت‌حاد، عفونت ادراری، درگیری کیسهٔ صفرا و عفونت زخم جراحی.</p>',
 'در شکل: «آزمون صفرا–اسکولین مثبت ← نمک ۶٫۵٪ ← رشد؟ انتروکوک». «تحمل صفرا» با «حل‌شدن در صفرا» دو مفهوم متفاوت است.',
 [q('طبق فلوچارت جزوه، گروه D غیرانتروکوکی را چگونه از انتروکوک جدا می‌کنیم؟','پس از نتیجهٔ آزمون صفرا–اسکولین مثبت، رشد در نمک ۶٫۵٪ بررسی می‌شود. رشد مثبت در شاخهٔ انتروکوک و عدم رشد در شاخهٔ گروه D غیرانتروکوکی قرار می‌گیرد.',['آزمون صفرا–اسکولین','نمک ۶٫۵٪','رشد/عدم رشد'],[33,34]),
 q('چه بیماری‌هایی برای انتروکوک در این فایل آمده است؟','اندوکاردیت تحت‌حاد، عفونت ادراری، درگیری کیسهٔ صفرا و عفونت زخم جراحی؛ در زمینه‌های مستعد و فرصت‌طلبی در جزوه مطرح‌اند.',['چهار مورد','زمینهٔ بیمار مستعد'],[34])],
 ['فلوچارت را با شاخهٔ مثبت و منفی بازسازی می‌کنم.','دو آزمون مرتبط با صفرا را یکی نمی‌گیرم.'])

source_questions = [
 q('پاتوژن‌های انسانی در کدام دسته‌بندی اکسیژنی قرار می‌گیرند؟','پاسخ خود جزوه: همهٔ انواع ممکن‌اند، ولی عمدتاً در دستهٔ بی‌هوازی اختیاری.',['قید عمدتاً','وجود دسته‌های دیگر'],[6],'پرسش داخل جزوه'),
 q('در کدام دستهٔ دمایی پاتوژن‌های انسانی وجود دارند؟','در پاسخ جزوه، عمدتاً مزوفیل به دلیل سازگاری با دمای بدن حدود ۳۷ درجه؛ دسته‌های دیگر هم ذکر شده‌اند.',['مزوفیل','دمای بدن','عدم تعمیم به همه'],[7],'پرسش داخل جزوه'),
 q('اکستراترموفیل‌ها در طبیعت کجا زندگی می‌کنند؟','جزوه چشمه‌های آب گرم، آتشفشان‌ها و محیط‌های مشابه با دمای بسیار بالا را مثال می‌زند.',['محیط داغ','دو مثال'],[7],'پرسش داخل جزوه'),
 q('۱. روش شناسایی این باکتری چیست؟','سؤال منبع نام باکتری را مشخص نکرده است. الگوی پاسخ: نمونهٔ مناسب ← کشت و رنگ گرم ← آزمایش اختصاصی. مثال پنوموکوک: اپتوچین، حل‌شدن در صفرا و آزمون تورم کپسولی (کوئلونگ)؛ مثال آگالاکتیه: کمپ در کنار ویژگی‌های پایه.',['نام باکتری را اول روشن کن','نمونه و کشت','آزمایش افتراقی متناسب'],[25,29,30,34],'پرسش جزوه · صفحهٔ ۳۴'),
 q('۲. بیماری‌های ایجادشده توسط باکتری کدام‌اند؟','نام گونه باید مشخص باشد. پایوژنز: فارنژیت، مخملک، عفونت‌های پوست/بافت نرم و عوارض پس از عفونت؛ پنوموکوک: اوتیت، سینوزیت، پنومونی و در تهاجم مننژیت و دیگر درگیری‌ها؛ آگالاکتیه: عفونت بارداری/نوزاد مثل سپسیس و مننژیت.',['نام گونه','بیماری‌های متناسب','عفونت فعال از عارضهٔ ایمنی جدا'],[22,23,24,25,28,29,34],'پرسش جزوه · صفحهٔ ۳۴'),
 q('۳. واکسن پنوموکوک از چه چیزی ساخته شده است؟','پلی‌ساکاریدهای کپسولی، آنتی‌ژن‌های اصلی واکسن پنوموکوک‌اند. در واکسن کونژوگه، این پلی‌ساکاریدها به پروتئین حامل متصل‌اند؛ ظرفیت واکسن تعداد سروتیپ‌های پوشش‌داده‌شده را نشان می‌دهد.',['کپسول','پلی‌ساکارید در توضیح جزوه','پلی‌ساکاریدی و کونژوگه'],[30,34],'پرسش جزوه · صفحهٔ ۳۴'),
 q('۴. آنتی‌بیوتیک انتخابی برای این باکتری چیست؟','سؤال منبع نام باکتری و شرایط را مشخص نمی‌کند. در جزوه برای پایوژنز پنی‌سیلین G آمده؛ برای پنوموکوک و ویریدانس داروهای دیگر و بحث مقاومت هم ذکر شده است. یک دارو را برای همهٔ استرپ‌ها قطعی ننویس؛ پاسخ باید نام گونه، محل عفونت و حساسیت دارویی را در نظر بگیرد.',['نام گونه و شرایط سؤال','پاسخ در چارچوب جزوه','عدم تعمیم درمان به همهٔ گروه'],[24,30,32,34],'پرسش جزوه · صفحهٔ ۳۴'),
 q('۵. عوارض پس از عفونت پایوژنز چیست؟','تب روماتیسمی و گلومرولونفریت پس از استرپتوکوک. اولی با شباهت آنتی‌ژنی و پاسخ علیه میزبان، دومی با رسوب کمپلکس ایمنی در کلیه توضیح داده می‌شود.',['نام هر دو','مکانیسم متفاوت'],[23,24,33,34],'پرسش با پاسخ داخل جزوه'),
 q('۶. روش درمان استرپتوکوک‌ها را نام ببرید.','پاسخ کوتاهِ خود جزوه: پنی‌سیلین و سفالوسپورین. این پاسخ کلی با بحث مقاومت و تفاوت گونه‌ها در فایل ساده‌سازی شده است؛ برای پاسخ درمانی دقیق نیاز به روشن‌شدن گونه و بررسی است.',['عبارت منبع','قید گونه و مقاومت','تفاوت گونه و حساسیت'],[24,30,32,34],'پرسش با پاسخ داخل جزوه'),
 q('۷. خصوصیات کلی استرپتوکوک‌ها را نام ببرید.','در درس: کوکسی گرم مثبت، معمولاً زنجیره‌ای، کاتالاز منفی، بدون حرکت و اسپور و بی‌هوازی اختیاری. نبود کپسول را همگانی نیاور، چون خود فایل برای چند گونه کپسول دارد.',['گرم و شکل','کاتالاز','حرکت و اسپور','نیاز اکسیژن','استثنای کپسول'],[20,21,25,27,28,34],'پرسش داخل جزوه'),
 q('۸. خصوصیت شاخص هر باکتری را نام ببرید.','پنوموکوک: کپسول و اپتوچین حساس؛ پایوژنز: گروه A، بتا، سم‌های تب‌زا؛ آگالاکتیه: گروه B و کمپ؛ ویریدانس: محور دهان/بیوفیلم و اپتوچین مقاوم؛ انتروکوک: رشد در نمک ۶٫۵٪ در فلوچارت.',['عامل شاخص را به گونه وصل کن','آزمایش/بیماری‌زایی را تفکیک کن'],[21,22,25,29,31,33,34],'پرسش با مثال داخل جزوه'),
 q('۹. یادداشت منبع: «از پایوژنز، موتانس و میتیس حتماً سؤال پرسیده می‌شود.»','این جمله تأکید داخل جزوه است. در این راهنما به معنی توجه بیشتر به این سه نام استفاده شده؛ تضمین یا پیش‌بینی مستقل دربارهٔ امتحان شما نیست.',['پایوژنز','موتانس','میتیس','تأکید منبع، نه تضمین'],[34],'یادداشت تأکیدی جزوه · سؤال نیست'),
 q('۱۰. روش تشخیص استرپتوکوک‌ها را نام ببرید.','پاسخ جزوه: کشت، آزمایش‌های بیوشیمیایی و روش‌های مولکولی. برای پاسخ کامل، رنگ گرم، کاتالاز، همولیز و آزمایش افتراقی متناسب با گونه را در مسیر قرار بده.',['کشت','بیوشیمیایی','مولکولی','آزمایش افتراقی'],[24,27,29,34],'پرسش با پاسخ داخل جزوه'),
 q('۱۱. اصلی‌ترین عامل بیماری‌زایی پنوموکوک چیست و چه نقشی دارد؟','کپسول. به فرار از شناسایی/فاگوسیتوز، اتصال، بیوفیلم و کاهش دسترسی دارو ارتباط داده شده است. محور اصلیِ پاسخ را بقا در برابر ایمنی بگذار.',['کپسول','فرار از ایمنی','نقش‌های ذکرشدهٔ منبع'],[28,29,35],'پرسش با پاسخ داخل جزوه'),
 q('۱۲. ویژگی‌های S. mitis را نام ببرید.','موتانس و میتیس از استرپتوکوک‌های ویریدانس‌اند: کوکسی گرم مثبت، کاتالاز منفی، بدون اسپور و حرکت. اعضای این گروه ممکن است آلفاهمولیتیک یا بدون همولیز باشند.',['شکل/آرایش/گرم','کاتالاز','اسپور/حرکت','اکسیژن','گروه ویریدانس'],[30,35],'پرسش با پاسخ داخل جزوه'),
 q('۱۳. الگوی همولیز ویریدانس‌ها چگونه است؟','ویریدانس‌ها می‌توانند آلفاهمولیتیک یا بدون همولیز باشند. نام این گروه به سبزیِ همولیز آلفا اشاره دارد، اما این ویژگی در همهٔ اعضا الزامی نیست.',['آلفا یا بدون همولیز','تغییرپذیری در اعضای گروه'],[33,35],'پرسش تکمیلی بر پایهٔ جدول جزوه'),
 q('۱۴. میتیس را چگونه از پنوموکوک تشخیص می‌دهیم؟','پاسخ جزوه: دیسک اپتوچین. در چارچوب جدول، پنوموکوک حساس و میتیس/ویریدانس مقاوم است. حل‌شدن در صفرا نیز معیار همراه در فایل است.',['اپتوچین','حساس در برابر مقاوم','صفرا به‌عنوان معیار همراه'],[32,33,35],'پرسش با پاسخ داخل جزوه'),
 q('۱۵. تفاوت کلونیزه‌شدن و اینفکشن چیست؟','کلونیزاسیون یعنی استقرار و تکثیر میکروب بدون ایجاد بیماری. عفونت، ورود و تکثیر عامل در میزبان همراه با تعامل زیستی و پاسخ میزبان است و می‌تواند بی‌علامت باشد؛ بیماری زمانی است که اختلال یا آسیب بالینی بروز کند.',['استقرار بدون بیماری','امکان عفونت بی‌علامت','تفاوت عفونت و بیماری'],[35],'پرسش با پاسخ داخل جزوه')
]

mixed = [
 q('۱. یک باکتری ناشناخته را چگونه مرحله‌به‌مرحله توصیف و شناسایی می‌کنید؟','اول ویژگی پایه را ثبت می‌کنم: گرم، شکل و آرایش. سپس کشت و آزمون‌های مناسب مثل کاتالاز و همولیز را وارد مسیر می‌کنم و به آزمایش افتراقی گونه می‌رسم. معیارهای رشد مثل اکسیژن، دما و pH اطلاعات تکمیلی‌اند.',['گرم/شکل/آرایش','کشت','آزمایش پایه','آزمایش اختصاصی','شرایط رشد'],[4,5,6,7,20,27]),
 q('۲. تفاوت دیوارهٔ دو گروه گرم را به نتیجهٔ رنگ‌آمیزی وصل کنید.','گرم مثبت پپتیدوگلیکان ضخیم و بدون غشای خارجی است؛ رنگ اولیه را پس از رنگ‌زدایی حفظ می‌کند و بنفش می‌ماند. گرم منفی پپتیدوگلیکان نازک‌تر بین دو غشا دارد؛ رنگ اولیه در رنگ‌زدایی از دست می‌رود و رنگ مقابل آن را صورتی می‌کند. LPS در غشای خارجی گروه دوم مطرح است.',['ساختار هر دو','مرحلهٔ رنگ‌زدایی','رنگ نهایی','LPS'],[9,10,11,12]),
 q('۳. منحنی رشد را رسم کنید و علت هر فاز را بنویسید.','چهار قسمت را رسم می‌کنم: تأخیری برای سازگاری؛ نمایی برای افزایش نمایی؛ سکون برای تعادل تکثیر و مرگ با کاهش غذا/تجمع مواد زائد؛ مرگ برای کاهش جمعیت زنده. محور زمان و تعداد زنده (در شکل لگاریتمی) را نام‌گذاری می‌کنم.',['محورهای روشن','چهار فاز به ترتیب','علت تغییر','جمعیت زنده'],[14,15]),
 q('۴. مقاومت چگونه با جهش و چگونه با انتقال ژنتیکی در بحث جزوه ارتباط دارد؟','جهش توالی دی‌ان‌ای خود باکتری را تغییر می‌دهد و ممکن است مزیت مقاومت بسازد. انتقال ژنتیکی دریافت مادهٔ ژنتیکی از بیرون است؛ دی‌ان‌ای آزاد، فاژ یا تماس در سه مسیر مطرح‌اند. ژن مقاومت می‌تواند روی پلاسمید یا عناصر متحرک باشد.',['تغییر توالی','دریافت دی‌ان‌ای','سه واسطه','پلاسمید/ترنسپوزون'],[16,17,18]),
 q('۵. برای یک کوکسی گرم مثبت، مسیر افتراق استاف و استرپ را بنویسید.','کاتالاز مسیر را جدا می‌کند: مثبت به سمت استاف و منفی به سمت استرپ در چارچوب جزوه. در استاف کواگولاز و سپس نووبیوسین در مثال‌های فایل مطرح‌اند؛ در استرپ همولیز و سپس آزمایشی مثل باسیتراسین، کمپ یا اپتوچین متناسب با گروه.',['کاتالاز','کواگولاز/نووبیوسین','همولیز','آزمایش متناسب'],[20,25,27,29]),
 q('۶. بیماری‌های پایوژنز را در سه دستهٔ حضور باکتری، سم و پیامد ایمنی دسته‌بندی کنید.','حضور/گسترش باکتری: فارنژیت و عفونت‌های پوست/بافت نرم. سم: مخملک و سندروم شوک سمی در توضیح جزوه. پیامد ایمنی: تب روماتیسمی و گلومرولونفریت. بعضی بیماری‌ها چند سازوکار دارند؛ دسته‌بندی برای روشن‌کردن محور اصلی است.',['سه دسته','مثال هر دسته','M و قلب','کمپلکس و کلیه'],[22,23,24,33]),
 q('۷. آگالاکتیه را از ویژگی آزمایشگاهی تا اهمیت مادر–نوزاد توضیح دهید.','گروه B و بتاهمولیتیک، در افتراق درسی مقاوم به باسیتراسین و کمپ مثبت. کمپ روی آگار خون‌دار با استاف اورئوس و همولیز سرپیکانی دیده می‌شود. کلونیزاسیون دستگاه تناسلی/رکتوم مادر با عفونت بارداری و عفونت نوزادی مثل سپسیس و مننژیت ارتباط دارد.',['گروه/همولیز','باسیتراسین','روش کمپ','محل مادر','پیامد نوزاد'],[20,25,28]),
 q('۸. پنوموکوک و ویریدانس را حداقل در پنج محور مقایسه کنید.','در درس هر دو کوکسی گرم مثبت و کاتالاز منفی‌اند. پنوموکوک معمولاً جفت نیزه‌ای، کپسول‌دار، حساس به اپتوچین، محلول در صفرا و آزمون تورم کپسولی (کوئلونگ) مثبت است؛ ویریدانس در جدول گرد/زنجیره‌ای، بدون کپسول، مقاوم به اپتوچین، نامحلول در صفرا و آزمون تورم کپسولی (کوئلونگ) منفی است. ویریدانس‌ها می‌توانند آلفاهمولیتیک یا بدون همولیز باشند.',['شباهت پایه','شکل/آرایش','کپسول','اپتوچین','صفرا','آزمون تورم کپسولی (کوئلونگ)','الگوی همولیز'],[28,29,32,33,35]),
 q('۹. چگونه مصرف قند و چسبندگی باکتری به از دست رفتن مواد معدنی مرتبط می‌شوند؟','اتصال و شبکهٔ گلوکان/پلی‌ساکارید، بیوفیلم پایدار می‌سازند. باکتری قادر به تحمل اسید، کربوهیدرات را مصرف و اسید تولید می‌کند. اسید با از دست رفتن مواد معدنی دندان و پیشروی پوسیدگی مرتبط است. مسیر التهاب لثه را جدا توضیح می‌دهم.',['چسبندگی','ماتریکس/بیوفیلم','تحمل اسید','تولید اسید','دمینرالیزاسیون','جداکردن التهاب لثه'],[31]),
 q('۱۰. دو آزمون مرتبط با صفرا و نقش نمک ۶٫۵٪ را توضیح دهید.','آزمون حلالیت در صفرا در افتراق پنوموکوک و ویریدانس، حل‌شدن/لیز را می‌سنجد. در فلوچارت گروه D، پس از آزمون صفرا–اسکولین مثبت، رشد در نمک ۶٫۵٪ شاخهٔ انتروکوک را از گروه D غیرانتروکوکی جدا می‌کند.',['دو آزمایش متفاوت','حل‌شدن پنوموکوک','آزمون صفرا–اسکولین','نمک ۶٫۵٪','دو شاخه'],[29,32,33,34])
]

