def persian_numbers(html):
    digits=str.maketrans('0123456789','۰۱۲۳۴۵۶۷۸۹')
    class Numerals(HTMLParser):
        def __init__(self):
            super().__init__(convert_charrefs=False)
            self.parts=[];self.raw_tag=None
        def handle_starttag(self,tag,attrs):
            raw=self.get_starttag_text()
            raw=re.sub(r'((?:aria-label|title)="[^"]*")',lambda m:m.group(0).translate(digits),raw)
            self.parts.append(raw)
            if tag in ('style','script'):self.raw_tag=tag
        def handle_startendtag(self,tag,attrs):self.parts.append(self.get_starttag_text())
        def handle_endtag(self,tag):
            self.parts.append('</'+tag+'>')
            if tag==self.raw_tag:self.raw_tag=None
        def handle_data(self,data):self.parts.append(data if self.raw_tag else data.translate(digits))
        def handle_entityref(self,name):self.parts.append('&'+name+';')
        def handle_charref(self,name):self.parts.append('&#'+name+';')
        def handle_comment(self,data):self.parts.append('<!--'+data+'-->')
        def handle_decl(self,decl):self.parts.append('<!'+decl+'>')
    parser=Numerals();parser.feed(html);parser.close()
    return ''.join(parser.parts)


